"""MetalABI.h from one kind's table (kinds/<kind>.json): the facts the frontend compiles in for that kind.

usage: gen.py <kinds/<kind>.json> <MetalABI.h>
"""

import json
import sys
from pathlib import Path

WIDTHS = {'I': 4, 'Q': 8}

HEADER = """\
// Generated by drivers/TegraGM20BMetal/abi/gen.py from kinds/{kind}.json: {kind}'s Metal.framework, as the plugin's
// device subclass depends on it. kLimitFields is the base class's limits table (-[_MTLDevice limits], the _limits
// ivar): each integer field _MTLDevice has an accessor of, at its offset in the table, with its width in bytes.
#pragma once
#include <cstddef>
#include <cstdint>

#define SWITCH_METAL_KIND "{kind}"
// The MTLCompiler image Metal itself loads: the frontend's in-process compiler (24B119 keeps it only under Versions/).
#define SWITCH_METAL_COMPILER "{compiler}"

inline constexpr size_t kMTLDeviceInstanceSize = {instance_size};
inline constexpr size_t kMTLDeviceLimitsBytes = {limits_bytes};

struct LimitField {{
    const char *selector;
    uint16_t offset;
    uint8_t bytes;
}};

inline constexpr LimitField kLimitFields[] = {{
{fields}
}};

// MTLSpecializeFunctionToArchive's request (MTLBuildRequestType 15) as this kind's Metal writes it and its MTLCompiler
// reads it (specialize_request): the header's size, which is where the data starts, and where each field sits in the
// header. constants, air and specializedName are a u32 offset and u32 size, name a u32 offset and u16 size with its
// NUL, requestType the type twice (asked, downgraded to) and hash the source function's 32-byte bitcode hash.
struct SpecializeRequestLayout {{
    uint16_t headerBytes, constants, name, air, specializedName, requestType, hash;
}};

inline constexpr SpecializeRequestLayout kSpecializeRequest = {{{specialize}}};
"""

SPECIALIZE_FIELDS = ('header_bytes', 'constants', 'name', 'air', 'specialized_name', 'request_type', 'hash')


def header(table: dict) -> str:
    device = table['MTLDevice']
    widths = {name: WIDTHS[kind] for name, (_, kind) in device['limits_fields'].items() if kind in WIDTHS}
    fields = '\n'.join(f'    {{"{name}", 0x{offset:x}, {widths[name]}}},' for name, offset in device['limits'].items())
    return HEADER.format(
        kind=table['kind'],
        compiler=table['compiler'],
        instance_size=device['instance_size'],
        limits_bytes=device['limits_bytes'],
        fields=fields,
        specialize=', '.join(f'0x{table["specialize_request"][name]:x}' for name in SPECIALIZE_FIELDS),
    )


def main() -> None:
    table, out = sys.argv[1:3]
    Path(out).write_text(header(json.loads(Path(table).read_text())))


if __name__ == '__main__':
    main()
